from pathlib import Path
import json

def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {'pass': False, 'score': 0.0, 'feedback': 'external_services_path is None; cannot check Slack data'}

    slack_path = Path(external_services_path) / 'slack_data.json'
    if not slack_path.exists():
        return {'pass': False, 'score': 0.0, 'feedback': f'slack_data.json not found at {slack_path}'}

    with open(slack_path) as f:
        data = json.load(f)

    messages_by_channel = data.get('messages', {})
    channels = data.get('channels', {})

    name_to_id = {ch_data.get('name', '').lower(): ch_id for ch_id, ch_data in channels.items()}

    total_messages = sum(len(msgs) for msgs in messages_by_channel.values())
    all_messages = [
        (channels.get(ch_id, {}).get('name', ch_id), msg.get('text', ''))
        for ch_id, msgs in messages_by_channel.items()
        for msg in msgs
    ]

    def normalize(s):
        # strip square brackets so "[RCM Manager]" matches "RCM Manager"
        return s.replace('[', '').replace(']', '').strip().lower()

    expected_escalation = ('rcm manager', 'clm-2026-0048', 'payer dispute', 'operational')
    expected_special_auth = ('clm-2026-0049', 'special action authorized')

    def contains_required(text, required):
        normalized = normalize(text)
        return all(token in normalized for token in required)

    escalations_id = name_to_id.get('escalations')
    escalations_msgs = messages_by_channel.get(escalations_id, []) if escalations_id else []
    if not escalations_msgs:
        for ch_id, msgs in messages_by_channel.items():
            if channels.get(ch_id, {}).get('name', '').lower() == 'escalations':
                escalations_msgs = msgs
                break

    escalation_found = any(
        contains_required(msg.get('text', ''), expected_escalation)
        for msg in escalations_msgs
    )

    special_auth_id = name_to_id.get('special-authorization')
    special_auth_msgs = messages_by_channel.get(special_auth_id, []) if special_auth_id else []
    if not special_auth_msgs:
        for ch_id, msgs in messages_by_channel.items():
            if 'special' in channels.get(ch_id, {}).get('name', '').lower() and 'auth' in channels.get(ch_id, {}).get('name', '').lower():
                special_auth_msgs = msgs
                break

    special_found = any(
        contains_required(msg.get('text', ''), expected_special_auth)
        for msg in special_auth_msgs
    )

    # Each sub-check is scored and reported separately so an extra/missing
    # message-count failure is distinguishable from a wrong-content failure.
    # Overall pass still requires every sub-check.
    checks = []

    # Sub-check 1: exact total message count, attributing every message.
    matching_escalation = 0
    matching_special_auth = 0
    unexpected_messages = []
    for ch_id, msgs in messages_by_channel.items():
        ch_name = str(channels.get(ch_id, {}).get('name', ch_id))
        for msg in msgs:
            text = msg.get('text', '')
            if ch_name.lower() == 'escalations' and contains_required(text, expected_escalation):
                matching_escalation += 1
            elif 'special' in ch_name.lower() and 'auth' in ch_name.lower() and contains_required(text, expected_special_auth):
                matching_special_auth += 1
            else:
                unexpected_messages.append((f'#{ch_name}', text))

    if total_messages != 2:
        checks.append((
            'message-count',
            False,
            f'Expected exactly 2 total Slack messages but found {total_messages}: {all_messages}; '
            f'messages matching the required #escalations post: {matching_escalation}; '
            f'matching the required #special-authorization post: {matching_special_auth}; '
            f'unexpected messages (channel, text): {unexpected_messages}'
        ))
    else:
        checks.append(('message-count', True, ''))

    # Sub-check 2: required #escalations message content.
    if escalation_found:
        checks.append(('escalations-content', True, ''))
    else:
        checks.append((
            'escalations-content',
            False,
            f'No #escalations message containing all required elements {expected_escalation}. Found: {[m.get("text") for m in escalations_msgs]}'
        ))

    # Sub-check 3: required #special-authorization message content.
    if special_found:
        checks.append(('special-authorization-content', True, ''))
    else:
        checks.append((
            'special-authorization-content',
            False,
            f'No #special-authorization message containing all required elements {expected_special_auth}. Found: {[m.get("text") for m in special_auth_msgs]}'
        ))

    passed_checks = sum(1 for _, ok, _ in checks if ok)
    if passed_checks < len(checks):
        statuses = ', '.join(f"[{label}]={'PASS' if ok else 'FAIL'}" for label, ok, _ in checks)
        details = '; '.join(f'[{label}] {detail}' for label, ok, detail in checks if not ok)
        return {'pass': False, 'score': passed_checks / len(checks), 'feedback': f'Sub-checks passed {passed_checks}/{len(checks)} ({statuses}); {details}'}

    return {'pass': True, 'score': 1.0, 'feedback': f'Slack verified: #escalations match for CLM-2026-0048/Operational; #special-authorization match for CLM-2026-0049; total messages=2'}

from pathlib import Path
from datetime import datetime, timedelta
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError
import json
import re

# Seeded google_calendar events (14 TFL deadlines, from the task's
# initial_external_services seed). Used only to attribute event-count
# failures to specific extra or missing events in feedback; the
# pass/fail conditions do not depend on this map.
SEED_EVENTS = {
    'evt-1': 'CLM-2026-0005 TFL Deadline',
    'evt-2': 'CLM-2026-0012 TFL Deadline',
    'evt-3': 'CLM-2026-0018 TFL Deadline',
    'evt-4': 'CLM-2026-0025 TFL Deadline',
    'evt-5': 'CLM-2026-0052 TFL Deadline',
    'evt-6': 'CLM-2026-0022 TFL Deadline',
    'evt-7': 'CLM-2026-0029 TFL Deadline',
    'evt-8': 'CLM-2026-0031 TFL Deadline',
    'evt-9': 'CLM-2026-0033 TFL Deadline',
    'evt-10': 'CLM-2026-0038 TFL Deadline',
    'evt-11': 'CLM-2026-0041 TFL Deadline',
    'evt-12': 'CLM-2026-0047 TFL Deadline',
    'evt-13': 'CLM-2026-0048 TFL Deadline',
    'evt-14': 'CLM-2026-0049 TFL Deadline',
}


def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {'pass': False, 'score': 0.0, 'feedback': 'external_services_path is None; cannot check calendar data'}

    cal_path = Path(external_services_path) / 'calendar_data.json'
    if not cal_path.exists():
        return {'pass': False, 'score': 0.0, 'feedback': f'calendar_data.json not found at {cal_path}'}

    with open(cal_path) as f:
        data = json.load(f)

    events_raw = data.get('events', {})
    if isinstance(events_raw, dict):
        events_list = list(events_raw.values())
        total_events = len(events_raw)
    elif isinstance(events_raw, list):
        events_list = events_raw
        total_events = len(events_raw)
    else:
        return {'pass': False, 'score': 0.0, 'feedback': f'Unexpected events format: {type(events_raw)}'}

    # Accept the summary with or without square brackets around each filled-in field.
    # \[? means "an optional [" and \]? means "an optional ]".
    # \s* allows for any extra spaces.
    summary_pattern = re.compile(
        r'^\s*'
        r'\[?\s*RCM Manager\s*\]?'
        r'\s*-\s*Claim ID:\s*'
        r'\[?\s*CLM-2026-0048\s*\]?'
        r'\s*;\s*Reason:\s*'
        r'\[?\s*Payer Dispute\s*\]?'
        r'\s*;\s*Escalation Category:\s*'
        r'\[?\s*Operational\s*\]?'
        r'\s*$',
        re.IGNORECASE,
    )

    # Each sub-check is scored and reported separately so a count failure
    # (extra or missing events) is distinguishable from a wrong-summary or
    # wrong-time failure. Overall pass still requires every sub-check.
    checks = []

    # Sub-check 1: exact event count, attributing every event to a cause.
    seed_summaries = set(SEED_EVENTS.values())
    seeded_present = 0
    escalation_matching = 0
    unexpected_events = []
    for event in events_list:
        event_id = str(event.get('id', '')).strip()
        summary = str(event.get('summary', '')).strip()
        if event_id in SEED_EVENTS or summary in seed_summaries:
            seeded_present += 1
        elif summary_pattern.match(summary):
            escalation_matching += 1
        else:
            unexpected_events.append((summary, str(event.get('start', ''))))

    if total_events != 15:
        present_ids = {str(e.get('id', '')).strip() for e in events_list}
        present_summaries = {str(e.get('summary', '')).strip() for e in events_list}
        missing_seeded = [
            eid for eid, seed_summary in SEED_EVENTS.items()
            if eid not in present_ids and seed_summary not in present_summaries
        ]
        detail = (
            f'Expected exactly 15 calendar events but found {total_events}; '
            f'seeded TFL events present: {seeded_present}/14; '
            f'events matching the required escalation summary: {escalation_matching}; '
            f'unexpected extra events (summary, start): {unexpected_events}'
        )
        if missing_seeded:
            detail += f'; missing seeded events: {missing_seeded}'
        checks.append(('event-count', False, detail))
    else:
        checks.append(('event-count', True, ''))

    # Sub-check 2: the required escalation event summary is present.
    target_event = None
    for event in events_list:
        summary = str(event.get('summary', '')).strip()
        if summary_pattern.match(summary):
            target_event = event
            break

    if target_event is None:
        all_summaries = [str(e.get('summary', '')) for e in events_list]
        checks.append((
            'escalation-summary',
            False,
            'No calendar event found with summary matching '
            '"RCM Manager - Claim ID: CLM-2026-0048; Reason: Payer Dispute; '
            'Escalation Category: Operational" (square brackets around field values are allowed). '
            f'Found summaries: {all_summaries}',
        ))
    else:
        checks.append(('escalation-summary', True, ''))

    def parse_datetime(value, label):
        if not isinstance(value, dict):
            return None, None, f'{label} must be a calendar dateTime object, got {value!r}'

        raw = value.get('dateTime')
        time_zone = value.get('timeZone')
        if not isinstance(raw, str) or not raw.strip():
            return None, time_zone, f'{label} has no dateTime value: {value!r}'

        normalized = raw.strip()
        if normalized.endswith('Z'):
            normalized = normalized[:-1] + '+00:00'
        try:
            parsed = datetime.fromisoformat(normalized)
        except ValueError:
            return None, time_zone, f'{label} is not a valid RFC3339 datetime: {raw!r}'
        if parsed.tzinfo is None or parsed.utcoffset() is None:
            if not isinstance(time_zone, str) or not time_zone.strip():
                return None, time_zone, f'{label} must include either a timezone offset or an explicit timeZone: {raw!r}'
            try:
                parsed = parsed.replace(tzinfo=ZoneInfo(time_zone.strip()))
            except ZoneInfoNotFoundError:
                return None, time_zone, f'{label} uses an unknown timeZone: {time_zone!r}'
        return parsed, time_zone, ''

    # Sub-checks 3 and 4: exact corrected one-minute interval.
    if target_event is None:
        checks.append(('start', False, 'Event start time not evaluated: no event matching the required escalation summary was found'))
        checks.append(('end', False, 'Event end time not evaluated: no event matching the required escalation summary was found'))
    else:
        start_value = target_event.get('start')
        end_value = target_event.get('end')
        start, start_zone, start_error = parse_datetime(start_value, 'Event start time')
        end, end_zone, end_error = parse_datetime(end_value, 'Event end time')

        start_expected = start is not None and (
            start.year,
            start.month,
            start.day,
            start.hour,
            start.minute,
            start.second,
            start.microsecond,
        ) == (2026, 2, 23, 15, 15, 0, 0)
        if start_error:
            start_detail = start_error
        elif not start_expected:
            start_detail = f'Event start must be exactly 3:15 PM on February 23, 2026, got {start_value!r}'
        else:
            start_detail = ''
        checks.append(('start', not start_detail, start_detail))

        end_expected = end is not None and (
            end.year,
            end.month,
            end.day,
            end.hour,
            end.minute,
            end.second,
            end.microsecond,
        ) == (2026, 2, 23, 15, 16, 0, 0)
        interval_expected = (
            start is not None
            and end is not None
            and end - start == timedelta(minutes=1)
        )
        timezone_preserved = (
            start is not None
            and end is not None
            and start.utcoffset() == end.utcoffset()
            and start_zone == end_zone
        )
        end_issues = []
        if end_error:
            end_issues.append(end_error)
        elif not end_expected:
            end_issues.append(f'Event end must be exactly 3:16 PM on February 23, 2026, got {end_value!r}')
        if start is not None and end is not None and not interval_expected:
            end_issues.append('Event must run for exactly one minute, from 3:15 PM to 3:16 PM')
        if start is not None and end is not None and not timezone_preserved:
            end_issues.append('Event start and end must preserve the same timezone')
        checks.append(('end', not end_issues, '; '.join(end_issues)))

    passed_checks = sum(1 for _, ok, _ in checks if ok)
    if passed_checks < len(checks):
        statuses = ', '.join(f"[{label}]={'PASS' if ok else 'FAIL'}" for label, ok, _ in checks)
        details = '; '.join(f'[{label}] {detail}' for label, ok, detail in checks if not ok)
        return {'pass': False, 'score': passed_checks / len(checks), 'feedback': f'Sub-checks passed {passed_checks}/{len(checks)} ({statuses}); {details}'}

    return {'pass': True, 'score': 1.0, 'feedback': f'Calendar verified: {total_events} events found; escalation event found with valid summary and exact one-minute interval from 3:15 PM to 3:16 PM on February 23, 2026'}

from pathlib import Path
import json

def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {'pass': False, 'score': 0.0, 'feedback': 'external_services_path is None; cannot check mailbox data'}

    mailbox_path = Path(external_services_path) / 'mailbox.json'
    if not mailbox_path.is_file():
        return {'pass': False, 'score': 0.0, 'feedback': f'mailbox.json not found at {mailbox_path}; cannot verify that no sent emails exist'}

    try:
        with open(mailbox_path) as f:
            data = json.load(f)
    except (OSError, json.JSONDecodeError) as exc:
        return {'pass': False, 'score': 0.0, 'feedback': f'Unable to read valid mailbox.json at {mailbox_path}: {exc}'}

    emails = data.get('emails', [])
    sent_emails = [e for e in emails if str(e.get('folder', '')).lower() == 'sent']

    if sent_emails:
        subjects = [e.get('subject', 'no subject') for e in sent_emails]
        return {'pass': False, 'score': 0.0, 'feedback': f'Found {len(sent_emails)} sent email(s) but expected none. Subjects: {subjects}'}

    return {'pass': True, 'score': 1.0, 'feedback': f'No sent emails found in mailbox. Total emails: {len(emails)}'}
